/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: release, recording, barcode, file, files, collection, song, answer, item, stageWith, queryOf
 *   Constants: guard
 * Tests
 *   - iTunes requests come from the run's planned queries: UPC lookups of a valid barcode by GS1 prefix, then the first text search by script, never a label
 *   - kept results are plausible by track count or a single file's duration, gain each storefront's names once, stop at four, and a UPC hit ends the UPC lookups
 *   - the bridge searches each result's distinct names: a recording search for a song, a release search without " - Single" or " - EP" for a collection, names that differ from the searched text first, at most four
 *   - a bridge ends found for a result one of whose searches found a release, unavailable when MusicBrainz was exhausted first, not run when refused or unsent, else no release
 *   - a song is resolved through its collection lookup, so a box set's sub-album named by the song is never taken as the album
 *   - a collection lookup that gives fewer songs than the collection has, or may be cut off at the lookup limit, gives an incomplete iTunes-only candidate
 *   - collection lookups stop at their bound: a further result is skipped without a request, making the stage incomplete
 *   - an iTunes-only release keeps the single artist string as one entry, milliseconds, discs in order, the day date, no label or country, a UPC barcode and allowlisted artwork only
 *   - each iTunes-only track is credited with its song's single artist string as one primary entry, never split, apart from the release credit
 *   - localized name groups are one result's distinct artist names across storefronts, case-folded, at least two, bounded, and a malformed stage gives none
 *   - a stored stage from another release is read without its unknown parts, and an unreadable one is none
 *   - iTunes unavailable skips its remaining requests; a result left without its collection lookup makes the stage incomplete, skipped searches do not
 *   - in subset mode a collection is kept with at least as many tracks as members or an unknown count, fewest extra first across the stage's answers, up to four; songs are unchanged
 *   - a review's stage that leaves out only collections with more tracks than members keeps its exact-count flag; an unknown or equal count, a song or an unknown member count clears it
 *   - a submitted Artist name is the iTunes term's artist, and a later release's Track-title search never gives an iTunes request
 * @end-catalog */

/**
 * The iTunes fallback stage, pure (lookupItunesStage.ts): which iTunes requests a run's planned queries give (term, entity,
 * storefronts by script and by GS1 prefix, no placeholder barcode), which results are kept (plausible by track count or duration,
 * names merged per storefront, the result bound), the bridge searches (song or collection, ` - Single`/` - EP` dropped, placeholder
 * artists left out, merged, bounded), the bridge outcome matrix, a box set's collection resolved through its collection lookup, the
 * release values of an iTunes-only candidate and the localized name groups. Names and IDs are synthetic; nothing reaches the network.
 */
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import { METADATA_LOOKUP_JOB_LIMITS, METADATA_LOOKUP_LIMITS, type ItunesCollection, type ItunesSearchResult, type ItunesTrack } from '../../src/administration/lookup/lookupContract';
import {
    finishItunesBridge, itunesCandidate, itunesCollectionTitle, itunesRelease, itunesRequestsFor, itunesUnavailable, lookupLocalizedGroups, nextItunesCollectionAction, nextItunesSearchAction,
    planItunesBridge, recordBridgeAnswer, recordItunesAnswer, recordItunesCollection, startItunesStage, storedItunesStage, type LookupItunesItem, type LookupItunesStage
} from '../../src/administration/lookup/lookupItunesStage';
import { planMetadataLookup, type PlannedLookupQuery } from '../../src/administration/lookup/lookupQueryPlanner';
import { proposalForRelease, rankLookupCandidates, trackArtistProposal, type LocalFileEvidence } from '../../src/administration/lookup/lookupRanking';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const release = (text: string, extra: Record<string, unknown> = {}, flags: Record<string, unknown> = {}): PlannedLookupQuery =>
    ({ kind: 'musicBrainzReleaseSearch', query: { release: text, ...extra }, basis: 'albumText', ...flags }) as PlannedLookupQuery;
const recording = (text: string, artist?: string): PlannedLookupQuery => ({ kind: 'musicBrainzRecordingSearch', query: { recording: text, ...(artist ? { artist } : {}) }, basis: 'songText' });
const barcode = (digits: string): PlannedLookupQuery => ({ kind: 'musicBrainzReleaseSearch', query: { barcode: digits }, basis: 'barcode' });
const file = (durationMs: number | null, durationPrecisionMs: 0 | 1000 = 0): LocalFileEvidence => ({ slotId: 'slot', order: 0, durationMs, durationPrecisionMs,
    discNumber: null, trackNumber: null, artistTags: [], identifiers: { releaseId: null, barcode: null, catalogNumber: null } });
const files = (count: number) => Array.from({ length: count }, (_unused, index) => ({ ...file(null), slotId: `slot-${index}`, order: index }));
const collection = (id: string, name: string, artist: string, trackCount: number | null, extra: Partial<ItunesCollection> = {}): ItunesCollection =>
    ({ collectionId: id, collectionName: name, artistName: artist, trackCount, releaseDate: { year: 2022, month: 8, day: 17 }, country: 'JPN', artworkUrl: null, ...extra });
const song = (trackId: string, collectionId: string, name: string, artist: string, extra: Partial<ItunesTrack> = {}): ItunesTrack => ({ trackId, collectionId, collectionName: null,
    trackName: name, artistName: artist, discNumber: 1, discCount: 1, trackNumber: 1, trackTimeMillis: 200_000, ...extra });
const answer = (collections: ItunesCollection[], tracks: ItunesTrack[] = []): ItunesSearchResult => ({ collections, tracks });
const item = (key: string, kind: LookupItunesItem['kind'], names: [string, string, 'us' | 'jp' | 'kr' | 'tw'][], extra: Partial<LookupItunesItem> = {}): LookupItunesItem => ({
    key, kind, collectionId: key.split(':')[1], names: names.map(([title, artist, storefront]) => ({ storefront, title, artist })), barcode: null, bridge: 'pending', collection: 'notNeeded', ...extra });
const stageWith = (items: LookupItunesItem[], text: string | null = null): LookupItunesStage => ({ reason: 'noMatch', text, requests: [], requestIndex: 0, items, bridge: null,
    bridgeIndex: 0, bridgeOutcomes: [], state: 'answered', complete: true, finalized: false });
const queryOf = (query: PlannedLookupQuery) => (query as { query: unknown }).query;

test('iTunes requests come from the run\'s planned queries: UPC lookups of a valid barcode by GS1 prefix, then the first text search by script, never a label', () => {
    // The credited release search names an artist and a label: the term is text and artist, never the label.
    assert.deepEqual(itunesRequestsFor([release('Hotel California', { artist: 'Eagles', label: 'Asylum Records' }), release('Hotel California')]), [
        { kind: 'itunesSearch', term: 'Hotel California Eagles', entity: 'album', storefront: 'us' }, { kind: 'itunesSearch', term: 'Hotel California Eagles', entity: 'album', storefront: 'jp' }]);
    // A recording search is a song search; kana puts jp first, Hangul kr, Han jp then tw.
    assert.deepEqual(itunesRequestsFor([recording('パンドラコール', 'ヰ世界情緒')]).map(request => [request.kind === 'itunesSearch' && request.entity, request.storefront]), [['song', 'jp'], ['song', 'us']]);
    assert.deepEqual(itunesRequestsFor([release('합성 앨범')]).map(request => request.storefront), ['kr', 'us']);
    assert.deepEqual(itunesRequestsFor([release('合成音楽集')]).map(request => request.storefront), ['jp', 'tw', 'us']);
    // A label-only credited search still searches the text alone; fallbacks are never the text search.
    assert.deepEqual(itunesRequestsFor([release('Synthetic Normalized', {}, { fallback: true }), release('Synthetic Album', { label: 'Synthetic Records' })]).map(request => request.kind === 'itunesSearch' && request.term),
        ['Synthetic Album', 'Synthetic Album']);
    // A barcode is looked up first, by GS1 prefix: a JAN (45x/49x) in jp, 880 in kr, 471 in tw, anything else in us then jp.
    const upc = (digits: string) => itunesRequestsFor([barcode(digits)]).map(request => request.kind === 'itunesUpc' ? `${request.storefront}:${request.barcode}` : request.kind);
    assert.deepEqual(upc('4582579942951'), ['jp:4582579942951', 'us:4582579942951']);
    assert.deepEqual(upc('4902102072915'), ['jp:4902102072915', 'us:4902102072915']);
    assert.deepEqual(upc('8801234567893'), ['kr:8801234567893', 'us:8801234567893']);
    assert.deepEqual(upc('4710000000004'), ['tw:4710000000004', 'us:4710000000004']);
    assert.deepEqual(upc('075596050920'), ['us:075596050920', 'jp:075596050920']);
    assert.deepEqual(itunesRequestsFor([barcode('075596050920'), release('Hotel California', { artist: 'Eagles' })]).map(request => request.kind), ['itunesUpc', 'itunesUpc', 'itunesSearch', 'itunesSearch']);
    // Placeholder barcodes (all zeros, a bad check digit, malformed) are never looked up.
    for (const digits of ['000000000000', '0000000000000', '075596050921', '07559605092', 'abc']) assert.deepEqual(upc(digits), [], digits);
    // Release ID and ISRC plans, and malformed stored queries, give none.
    assert.deepEqual(itunesRequestsFor([{ kind: 'musicBrainzRelease', releaseId: '0000000d-0000-4000-8000-000000000001', basis: 'releaseId' }, { kind: 'musicBrainzIsrc', isrc: 'JPY392200483', basis: 'isrc' }]), []);
    assert.deepEqual(itunesRequestsFor([null, 'text', { kind: 'musicBrainzReleaseSearch', basis: 'albumText' }, { kind: 'musicBrainzReleaseSearch', basis: 'albumText', query: { release: 7 } }] as unknown[]), []);
    assert.deepEqual(itunesRequestsFor('not a list' as unknown as unknown[]), []);
    assert.equal(startItunesStage([barcode('000000000000')], 'noMatch'), null);
    assert.deepEqual(startItunesStage([recording('Pandora Call')], 'searchUnavailable'), { reason: 'searchUnavailable', text: 'pandora call', requests: [
        { kind: 'itunesSearch', term: 'Pandora Call', entity: 'song', storefront: 'us' }, { kind: 'itunesSearch', term: 'Pandora Call', entity: 'song', storefront: 'jp' }],
        requestIndex: 0, items: [], bridge: null, bridgeIndex: 0, bridgeOutcomes: [], state: 'running', complete: true, finalized: false });
});

test('kept results are plausible by track count or a single file\'s duration, gain each storefront\'s names once, stop at four, and a UPC hit ends the UPC lookups', () => {
    const albums = startItunesStage([release('Synthetic Album', { artist: 'Synthetic Artist' })], 'noMatch')!;
    // Two files: a two-track or unknown-count collection is plausible, a three-track one is not.
    let stage = recordItunesAnswer(albums, 0, answer([collection('1', 'Two', 'A', 2), collection('2', 'Three', 'A', 3), collection('3', 'Unknown', 'A', null)]), files(2));
    assert.deepEqual([stage.requestIndex, stage.items.map(entry => [entry.key, entry.kind, entry.names])], [1, [
        ['collection:1', 'collection', [{ storefront: 'us', title: 'Two', artist: 'A' }]], ['collection:3', 'collection', [{ storefront: 'us', title: 'Unknown', artist: 'A' }]]]]);
    // The jp storefront shows the same collection under its own names (kept once per storefront), and three more plausible ones:
    // the fourth kept fills the bound, the fifth makes the stage incomplete. A stale answer for an earlier request is ignored.
    stage = recordItunesAnswer(stage, 1, answer([collection('1', 'ツー', 'エー', 2), collection('1', 'Again', 'A', 2), collection('4', 'Four', 'B', 2), collection('5', 'Five', 'C', 2), collection('6', 'Six', 'D', 2)]), files(2));
    assert.deepEqual([stage.complete, stage.items.map(entry => entry.key), stage.items[0].names.map(name => `${name.storefront}:${name.title}/${name.artist}`)],
        [false, ['collection:1', 'collection:3', 'collection:4', 'collection:5'], ['us:Two/A', 'jp:ツー/エー']]);
    assert.equal(recordItunesAnswer(stage, 0, answer([collection('9', 'Late', 'Z', 2)]), files(2)), stage);
    // A one-file song search keeps songs within the duration tolerance (3 s, plus a legacy file's 1-second precision); an unknown
    // duration on either side keeps the song.
    const songs = startItunesStage([recording('Synthetic Song')], 'noMatch')!;
    const heard = answer([], [song('11', '21', 'Near', 'A', { trackTimeMillis: 203_000 }), song('12', '22', 'Far', 'A', { trackTimeMillis: 203_001 }), song('13', '23', 'Unknown', 'A', { trackTimeMillis: null })]);
    assert.deepEqual(recordItunesAnswer(songs, 0, heard, [file(200_000)]).items.map(entry => entry.key), ['song:11', 'song:13']);
    assert.deepEqual(recordItunesAnswer(songs, 0, heard, [file(200_000, 1000)]).items.map(entry => entry.key), ['song:11', 'song:12', 'song:13']);
    assert.deepEqual(recordItunesAnswer(songs, 0, heard, [file(null)]).items.map(entry => [entry.key, entry.collectionId]), [['song:11', '21'], ['song:12', '22'], ['song:13', '23']]);
    // A UPC lookup that answers a collection ends the UPC lookups; one that answers none moves to the next storefront.
    const upc = startItunesStage([barcode('4582579942951'), release('Synthetic Album')], 'noMatch')!;
    assert.deepEqual(recordItunesAnswer(upc, 0, null, files(2)).requestIndex, 1);
    const hit = recordItunesAnswer(upc, 0, answer([collection('7', 'Found', 'A', 9)]), files(2));
    assert.deepEqual([hit.requestIndex, upc.requests[hit.requestIndex].kind, hit.items], [2, 'itunesSearch', []]);
    assert.equal(recordItunesAnswer(upc, 0, answer([collection('7', 'Found', 'A', 2)]), files(2)).items[0].barcode, '4582579942951');
});

test('the bridge searches each result\'s distinct names: a recording search for a song, a release search without " - Single" or " - EP" for a collection, names that differ from the searched text first, at most four', () => {
    const stage = stageWith([
        item('song:1', 'song', [['PANDORA CALL', 'Isekaijoucho', 'us'], ['パンドラコール', 'ヰ世界情緒', 'jp'], ['pandora call', 'ISEKAIJOUCHO', 'kr']]),
        item('collection:2', 'collection', [['パンドラコール - Single', 'ヰ世界情緒', 'jp']]),
        item('collection:3', 'collection', [['Synthetic Hits - EP', 'Various Artists', 'us'], ['Synthetic Hits - EP (Deluxe)', '[unknown]', 'jp']]),
        item('song:4', 'song', [['Overflow', 'Someone', 'us']])], 'pandora call');
    const planned = planItunesBridge(stage, false);
    assert.deepEqual(planned.bridge!.map(query => [query.kind, queryOf(query), query.basis, query.itemKeys]), [
        ['musicBrainzRecordingSearch', { recording: 'パンドラコール', artist: 'ヰ世界情緒' }, 'songText', ['song:1']],
        ['musicBrainzReleaseSearch', { release: 'パンドラコール', artist: 'ヰ世界情緒' }, 'albumText', ['collection:2']],
        // A placeholder artist is left out; only a trailing suffix is dropped.
        ['musicBrainzReleaseSearch', { release: 'Synthetic Hits' }, 'albumText', ['collection:3']],
        ['musicBrainzReleaseSearch', { release: 'Synthetic Hits - EP (Deluxe)' }, 'albumText', ['collection:3']]]);
    // The overflow (the remaining names, case-folded pairs counted once) is never sent: those results are marked unbridged.
    assert.deepEqual([planned.items.map(entry => entry.unbridged === true), planned.bridgeOutcomes], [[true, false, false, true], ['unsent', 'unsent', 'unsent', 'unsent']]);
    assert.equal(planItunesBridge(planned, false), planned);
    assert.deepEqual([itunesCollectionTitle('Album - Single'), itunesCollectionTitle('Album - EP'), itunesCollectionTitle('Album - Single (Live)'), itunesCollectionTitle('Album -Single')],
        ['Album', 'Album', 'Album - Single (Live)', 'Album -Single']);
    // The same search for two results is sent once for both.
    const shared = planItunesBridge(stageWith([item('song:5', 'song', [['Same', 'Artist', 'jp']]), item('song:6', 'song', [['same', 'artist', 'us']])]), false);
    assert.deepEqual(shared.bridge!.map(query => query.itemKeys), [['song:5', 'song:6']]);
    // A name that cannot be built (a link) is never sent; with MusicBrainz exhausted there is no bridge at all.
    const link = planItunesBridge(stageWith([item('song:7', 'song', [['https://example.test/song', 'Artist', 'us']])]), false);
    assert.deepEqual([link.bridge, link.items[0].unbridged], [[], true]);
    assert.deepEqual(planItunesBridge(stage, true).bridge, []);
});

test('a bridge ends found for a result one of whose searches found a release, unavailable when MusicBrainz was exhausted first, not run when refused or unsent, else no release', () => {
    const items = ['song:1', 'song:2', 'song:3', 'song:4', 'song:5'].map(key => item(key, 'song', [[key, 'Artist', 'us']]));
    const base = { ...stageWith(items), bridge: [
        { ...recording('a'), itemKeys: ['song:1', 'song:2'] }, { ...recording('b'), itemKeys: ['song:2', 'song:3'] }, { ...recording('c'), itemKeys: ['song:4'] }, { ...recording('d'), itemKeys: ['song:5'] }] };
    let stage: LookupItunesStage = { ...base, bridgeOutcomes: ['unsent', 'unsent', 'unsent', 'unsent'] };
    stage = recordBridgeAnswer(stage, 0, 'none');
    stage = recordBridgeAnswer(stage, 2, 'found');
    stage = recordBridgeAnswer(stage, 1, 'found');
    stage = recordBridgeAnswer(stage, 2, 'refused');
    assert.deepEqual([stage.bridgeIndex, stage.bridgeOutcomes], [3, ['none', 'found', 'refused', 'unsent']]);
    const ended = finishItunesBridge(stage, false);
    assert.deepEqual(ended.items.map(entry => [entry.key, entry.bridge, entry.collection]), [['song:1', 'noRelease', 'pending'], ['song:2', 'found', 'notNeeded'],
        ['song:3', 'found', 'notNeeded'], ['song:4', 'notRun', 'pending'], ['song:5', 'notRun', 'pending']]);
    assert.equal(finishItunesBridge(ended, true), ended);
    // MusicBrainz exhausted: what was not answered is unavailable, what was answered stays.
    assert.deepEqual(finishItunesBridge(stage, true).items.map(entry => entry.bridge), ['noRelease', 'found', 'found', 'notRun', 'unavailable']);
    // An unbridged result is not run even when its sent searches found nothing; two results of one collection need one lookup.
    const twin = finishItunesBridge({ ...stageWith([item('song:8', 'song', [['x', 'y', 'us']], { collectionId: '9', unbridged: true }), item('collection:9', 'collection', [['x', 'y', 'us']])]),
        bridge: [{ ...recording('x'), itemKeys: ['song:8', 'collection:9'] }], bridgeIndex: 1, bridgeOutcomes: ['none'] }, false);
    assert.deepEqual(twin.items.map(entry => [entry.bridge, entry.collection]), [['notRun', 'pending'], ['noRelease', 'notNeeded']]);
    // The next actions: no bridge search once MusicBrainz is exhausted, then each pending collection lookup in its first storefront.
    const searching = nextItunesSearchAction({ ...stage, state: 'answered' }, true);
    assert.equal(searching.action, null);
    const collected = nextItunesCollectionAction(searching.stage, 0, true);
    assert.deepEqual(collected.action, { kind: 'itunesCollection', itemKey: 'song:1', collectionId: '1', storefront: 'us' });
});

test('a song is resolved through its collection lookup, so a box set\'s sub-album named by the song is never taken as the album', () => {
    // The song search names the song's collection "Hotel California", but its collection is a box set.
    const stage = recordItunesAnswer(startItunesStage([recording('Hotel California', 'Eagles')], 'noMatch')!, 0,
        answer([], [song('31', '777', 'Hotel California', 'Eagles', { collectionName: 'Hotel California', trackTimeMillis: 391_357 })]), [file(391_000)]);
    const bridged = nextItunesSearchAction({ ...stage, requestIndex: stage.requests.length }, false);
    // The bridge is a recording search: "Hotel California" is never sent as a release.
    assert.deepEqual([bridged.action?.kind, bridged.action && 'query' in bridged.action ? bridged.action.query : null],
        ['bridge', { kind: 'musicBrainzRecordingSearch', query: { recording: 'Hotel California', artist: 'Eagles' }, basis: 'songText' }]);
    assert.ok(bridged.stage.bridge!.every(query => query.kind !== 'musicBrainzReleaseSearch'));
    const none = finishItunesBridge(recordBridgeAnswer(bridged.stage, 0, 'none'), false);
    const lookup = nextItunesCollectionAction(none, 0, false).action;
    assert.deepEqual(lookup, { kind: 'itunesCollection', itemKey: 'song:31', collectionId: '777', storefront: 'us' });
    const boxSet = answer([collection('777', 'The Studio Albums 1972-1979', 'Eagles', 3)], [song('31', '777', 'Hotel California', 'Eagles', { collectionName: 'Hotel California', trackNumber: 1, discNumber: 5 }),
        song('32', '777', 'New Kid In Town', 'Eagles', { trackNumber: 2, discNumber: 5 }), song('33', '777', 'Take It Easy', 'Eagles', { trackNumber: 1, discNumber: 1 })]);
    const candidate = itunesCandidate(none.items[0], boxSet)!;
    assert.deepEqual([candidate.key, candidate.releaseId, candidate.release!.title, proposalForRelease(candidate.release!).albumTitle], ['itunes:777', '777', 'The Studio Albums 1972-1979', 'The Studio Albums 1972-1979']);
    // The box set's three tracks never match the one file the song matched, so it is neither a matching group nor preselected.
    const ranked = rankLookupCandidates([{ key: candidate.key, source: 'itunes', releaseId: '777', itunesCheck: 'noRelease', summary: null, release: candidate.release }], [file(391_000)]);
    assert.deepEqual([ranked.candidates[0].status, ranked.candidates[0].comparison?.trackCount, ranked.groups.length, ranked.preselection], ['notMatching', { local: 1, candidate: 3 }, 0, null]);
    // An answer without that collection, or without its songs, gives no candidate; a found result never becomes one.
    assert.equal(itunesCandidate(none.items[0], answer([collection('778', 'Other', 'Eagles', 1)], [song('34', '778', 'Other', 'Eagles')])), null);
    assert.equal(itunesCandidate(none.items[0], answer([collection('777', 'The Studio Albums 1972-1979', 'Eagles', 3)])), null);
    assert.equal(itunesCandidate({ ...none.items[0], bridge: 'found' }, boxSet), null);
    assert.equal(itunesCandidate(none.items[0], null), null);
});

test('a collection lookup that gives fewer songs than the collection has, or may be cut off at the lookup limit, gives an incomplete iTunes-only candidate', () => {
    const pending = item('collection:12', 'collection', [['Twelve', 'Synthetic Ensemble', 'us']], { bridge: 'noRelease', collection: 'pending' });
    const songs = (count: number) => Array.from({ length: count }, (_unused, index) => song(String(1000 + index), '12', `Song ${index + 1}`, 'Synthetic Ensemble', { trackNumber: index + 1 }));
    // A 12-track collection answered with 11 songs (one not offered in that storefront) keeps no release, only the reported count.
    const short = itunesCandidate(pending, answer([collection('12', 'Twelve', 'Synthetic Ensemble', 12)], songs(11)))!;
    assert.deepEqual([short.key, short.details, short.release, short.reportedTrackCount, short.itunes?.check], ['itunes:12', 'omitted', null, 12, 'noRelease']);
    // Against the 11 files its songs would match, it is incomplete: never matching or preselected, and its 12 tracks cannot match
    // them; against 12 files it could, so that comparison is partial.
    const rank = (count: number) => rankLookupCandidates([{ key: short.key, source: 'itunes', releaseId: '12', itunesCheck: 'noRelease', summary: null, release: short.release,
        reportedTrackCount: short.reportedTrackCount }], files(count).map(entry => ({ ...entry, durationMs: 200_000 })));
    assert.deepEqual([rank(11).candidates[0].status, rank(11).groups.length, rank(11).preselection, rank(11).disclosure.partialComparison], ['incomplete', 0, null, false]);
    assert.deepEqual([rank(12).candidates[0].status, rank(12).preselection, rank(12).disclosure.partialComparison], ['incomplete', null, true]);
    // Every song answered: a complete release.
    assert.deepEqual([itunesCandidate(pending, answer([collection('12', 'Twelve', 'Synthetic Ensemble', 12)], songs(12)))!.details], ['fetched']);
    // Without a track count, an answer that fills the lookup limit (one place is the collection's) may be cut off.
    const limit = METADATA_LOOKUP_LIMITS.itunesLookupLimit;
    const unknown = (count: number) => itunesCandidate(pending, answer([collection('12', 'Twelve', 'Synthetic Ensemble', null)], songs(count)))!;
    assert.deepEqual([unknown(limit - 1).details, unknown(limit - 1).reportedTrackCount, unknown(limit - 2).details], ['omitted', undefined, 'fetched']);
});

test('collection lookups stop at their bound: a further result is skipped without a request, making the stage incomplete', () => {
    const results = Array.from({ length: METADATA_LOOKUP_JOB_LIMITS.itunesCollectionLookups + 1 }, (_unused, index) =>
        item(`collection:${index + 1}`, 'collection', [[`Album ${index}`, 'Synthetic Ensemble', 'us']], { bridge: 'noRelease', collection: 'pending' }));
    // Each lookup with an outcome (fetched, missing, failed or skipped after it was sent) counts toward the bound.
    const looked = { ...stageWith(results.map((entry, index) => index < METADATA_LOOKUP_JOB_LIMITS.itunesCollectionLookups
        ? { ...entry, collection: (['fetched', 'missing', 'failed', 'skipped'] as const)[index % 4] } : entry)), finalized: true };
    const next = nextItunesCollectionAction(looked, 0, false);
    assert.deepEqual([next.action, next.stage.items.at(-1)!.collection, next.stage.complete], [null, 'skipped', false]);
    // Below the bound the pending result is looked up.
    const below = { ...looked, items: looked.items.slice(1) };
    assert.deepEqual(nextItunesCollectionAction(below, 0, false).action, { kind: 'itunesCollection', itemKey: `collection:${results.length}`, collectionId: String(results.length), storefront: 'us' });
});

test('an iTunes-only release keeps the single artist string as one entry, milliseconds, discs in order, the day date, no label or country, a UPC barcode and allowlisted artwork only', () => {
    const artwork = 'https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/53/0f/80/530f802b/ANTCD-46555.jpg/100x100bb.jpg';
    const built = itunesRelease(collection('1613862586', 'ブルーアーカイブ  Original Soundtrack - Single', 'ミツキヨ、KARUT、Nor', 4, { artworkUrl: artwork }), [
        song('4', '1613862586', 'Fourth', 'ミツキヨ', { discNumber: 2, trackNumber: 2, trackTimeMillis: 123_456 }), song('3', '1613862586', 'Third', 'ミツキヨ', { discNumber: 2, trackNumber: 1, trackTimeMillis: 0 }),
        song('2', '1613862586', 'Second', 'KARUT', { discNumber: null, trackNumber: 2, trackTimeMillis: 200_001 }), song('1', '1613862586', 'First', 'Nor', { discNumber: 1, trackNumber: 1, trackTimeMillis: 99_999 })],
    '4580760834214');
    assert.deepEqual([built.releaseId, built.title, built.artistCredit, built.labels, built.country, built.date, built.groupFirstReleaseDate, built.barcode, built.trackCount, built.frontArtwork], [
        '1613862586', 'ブルーアーカイブ  Original Soundtrack - Single', [{ name: 'ミツキヨ、KARUT、Nor', joinPhrase: '', artistId: '', artistName: 'ミツキヨ、KARUT、Nor' }], [], null,
        { year: 2022, month: 8, day: 17 }, null, '4580760834214', 4, true]);
    assert.deepEqual(built.media.map(medium => [medium.position, medium.tracks.map(track => [track.position, track.title, track.lengthMs, track.recordingId, track.isrcs])]), [
        [1, [[1, 'First', 99_999, '', []], [2, 'Second', 200_001, '', []]]], [2, [[1, 'Third', null, '', []], [2, 'Fourth', 123_456, '', []]]]]);
    // One primary entry with no MusicBrainz ID, never split, as the draft would write it; no label; the iTunes day date.
    const proposal = proposalForRelease(built);
    assert.deepEqual([proposal.artists, proposal.label, proposal.releaseDate], [[{ name: 'ミツキヨ、KARUT、Nor', role: 'primary', joinPhrase: null, musicBrainzId: null }], null, { year: 2022, month: 8, day: 17 }]);
    assert.deepEqual(proposalForRelease(itunesRelease(collection('5', 'X', 'Synthetic A feat. Synthetic B', 1), [song('6', '5', 'X', 'A')], null)).artists,
        [{ name: 'Synthetic A feat. Synthetic B', role: 'primary', joinPhrase: null, musicBrainzId: null }]);
    // No barcode unless a UPC lookup found it; artwork only on the fixed artwork hosts.
    const plain = itunesRelease(collection('5', 'X', 'A', 1, { artworkUrl: 'https://example.test/image/thumb/x/100x100bb.jpg' }), [song('6', '5', 'X', 'A')], null);
    assert.deepEqual([plain.barcode, plain.barcodeText, plain.frontArtwork], [null, null, false]);
    assert.equal(itunesRelease(collection('5', 'X', 'A', 1), [song('6', '5', 'X', 'A')], '000000000000').barcode, null);
});

test('each iTunes-only track is credited with its song\'s single artist string as one primary entry, never split, apart from the release credit', () => {
    const built = itunesRelease(collection('5', 'X', 'Synthetic Ensemble', 2), [song('6', '5', 'One', 'Synthetic A feat. Synthetic B', { trackNumber: 1 }),
        song('7', '5', 'Two', 'Synthetic Ensemble', { trackNumber: 2 })], null);
    assert.deepEqual(built.media[0].tracks.map(track => track.artistCredit), [
        [{ name: 'Synthetic A feat. Synthetic B', joinPhrase: '', artistId: '', artistName: 'Synthetic A feat. Synthetic B' }],
        [{ name: 'Synthetic Ensemble', joinPhrase: '', artistId: '', artistName: 'Synthetic Ensemble' }]]);
    assert.deepEqual(built.media[0].tracks.map(track => trackArtistProposal(built, track)), [
        { artists: [{ name: 'Synthetic A feat. Synthetic B', role: 'primary', joinPhrase: null, musicBrainzId: null }] },
        { artists: [{ name: 'Synthetic Ensemble', role: 'primary', joinPhrase: null, musicBrainzId: null }] }]);
    // The Album's entries still come from the collection's artist string alone.
    assert.deepEqual(proposalForRelease(built).artists, [{ name: 'Synthetic Ensemble', role: 'primary', joinPhrase: null, musicBrainzId: null }]);
});

test('localized name groups are one result\'s distinct artist names across storefronts, case-folded, at least two, bounded, and a malformed stage gives none', () => {
    const stage = stageWith([
        item('song:1', 'song', [['A', 'Isekaijoucho', 'us'], ['B', 'ヰ世界情緒', 'jp'], ['C', 'ISEKAIJOUCHO', 'kr']]),
        item('song:2', 'song', [['A', 'Same', 'us'], ['B', 'same', 'jp']]),
        item('song:3', 'song', [['A', 'ヰ世界情緒', 'jp'], ['B', 'isekaijoucho', 'us']]),
        item('song:4', 'song', [['A', 'Various Artists', 'us'], ['B', 'Real', 'jp']])]);
    assert.deepEqual(lookupLocalizedGroups({ itunesStage: stage }), [['Isekaijoucho', 'ヰ世界情緒']]);
    const many = stageWith(Array.from({ length: 4 }, (_unused, index) => item(`song:${index + 1}`, 'song', [['A', `Name ${index}`, 'us'], ['B', `名前 ${index}`, 'jp'], ['C', `이름 ${index}`, 'kr'], ['D', `名 ${index}`, 'tw']])));
    assert.deepEqual(lookupLocalizedGroups({ itunesStage: many }).map(group => group.length), [4, 4, 4, 4]);
    assert.deepEqual(lookupLocalizedGroups({ itunesStage: stageWith([item('song:1', 'song', [['A', 'x'.repeat(201), 'us'], ['B', 'Short', 'jp']])]) }), []);
    for (const raw of [null, undefined, {}, { itunesStage: 'x' }, { itunesStage: { reason: 'other' } }]) assert.deepEqual(lookupLocalizedGroups(raw as never), []);
});

test('a stored stage from another release is read without its unknown parts, and an unreadable one is none', () => {
    const stage = recordItunesAnswer(startItunesStage([barcode('4582579942951'), recording('Song', 'Artist')], 'noMatch')!, 0, null, [file(null)]);
    assert.deepEqual(storedItunesStage(JSON.parse(JSON.stringify(stage))), stage);
    const foreign = { ...stage, requests: [...stage.requests, { kind: 'deezerSearch', term: 'x', storefront: 'us' }, { kind: 'itunesSearch', term: 'x', entity: 'video', storefront: 'us' }],
        items: [item('song:1', 'song', [['A', 'B', 'us']]), { key: 'song:2', kind: 'video', collectionId: '3', names: [], bridge: 'pending', collection: 'notNeeded' }],
        requestIndex: 99, bridge: [{ ...recording('A'), itemKeys: ['song:1'] }, { kind: 'deezer', itemKeys: [] }], bridgeIndex: -1, bridgeOutcomes: ['other'] };
    const read = storedItunesStage(foreign)!;
    assert.deepEqual([read.requests.length, read.requestIndex, read.items.map(entry => entry.key), read.bridge!.length, read.bridgeIndex, read.bridgeOutcomes],
        [stage.requests.length, stage.requests.length, ['song:1'], 1, 0, ['unsent']]);
    for (const raw of [null, 'x', { ...stage, reason: 'later' }, { ...stage, state: 'paused' }]) assert.equal(storedItunesStage(raw), null);
});

test('iTunes unavailable skips its remaining requests; a result left without its collection lookup makes the stage incomplete, skipped searches do not', () => {
    const early = itunesUnavailable(startItunesStage([recording('Synthetic Song')], 'noMatch')!);
    assert.deepEqual([early.state, early.requestIndex, early.complete, nextItunesSearchAction(early, false).action], ['unavailable', 2, true, null]);
    const late = itunesUnavailable({ ...stageWith([item('song:1', 'song', [['A', 'B', 'us']], { bridge: 'noRelease', collection: 'pending' })]), finalized: true });
    assert.deepEqual([late.items[0].collection, late.complete], ['failed', false]);
    // Unavailable before the bridge ended: the collection lookups the bridge then needs fail without a request.
    const unfinished = nextItunesCollectionAction({ ...stageWith([item('song:2', 'song', [['A', 'B', 'us']])]), state: 'unavailable', bridge: [], bridgeOutcomes: [] }, 0, false);
    assert.deepEqual([unfinished.action, unfinished.stage.items[0].bridge, unfinished.stage.items[0].collection, unfinished.stage.complete], [null, 'notRun', 'failed', false]);
});

test('in subset mode a collection is kept with at least as many tracks as members or an unknown count, fewest extra first across the stage\'s answers, up to four; songs are unchanged', () => {
    const albums = startItunesStage([release('Synthetic Album', { artist: 'Synthetic Artist' })], 'noMatch', 'subset')!;
    const plain = startItunesStage([release('Synthetic Album', { artist: 'Synthetic Artist' })], 'noMatch')!;
    // A review's stage starts with its own exact-count flag; an import's has none.
    assert.deepEqual([albums.exactComplete, 'exactComplete' in plain], [true, false]);
    const offered = answer([collection('1', 'One', 'A', 1), collection('2', 'Five', 'A', 5), collection('3', 'Unknown', 'A', null), collection('4', 'Two', 'A', 2),
        collection('5', 'Three', 'A', 3), collection('6', 'None', 'A', 0), collection('7', 'Also Two', 'A', 2)]);
    // Two members: the two two-track collections in answer order, then three and five tracks, each with its reported count; the
    // unknown count is left out by the bound, and could have exactly two tracks, so both flags clear. Fewer tracks than members, or
    // a known none, is never plausible.
    const kept = recordItunesAnswer(albums, 0, offered, files(2), 'subset');
    assert.deepEqual([kept.items.map(entry => [entry.key, entry.trackCount]), kept.complete, kept.exactComplete],
        [[['collection:4', 2], ['collection:7', 2], ['collection:5', 3], ['collection:2', 5]], false, false]);
    // Results are ordered across answers: a later answer's better fit displaces a larger result kept earlier.
    const first = recordItunesAnswer(albums, 0, answer([collection('2', 'Five', 'A', 5), collection('3', 'Unknown', 'A', null)]), files(2), 'subset');
    assert.deepEqual([first.items.map(entry => entry.key), first.complete, first.exactComplete], [['collection:2', 'collection:3'], true, true]);
    const later = recordItunesAnswer(first, 1, answer([collection('4', 'Two', 'A', 2), collection('5', 'Three', 'A', 3), collection('7', 'Also Two', 'A', 2)]), files(2), 'subset');
    assert.deepEqual([later.items.map(entry => entry.key), later.complete, later.exactComplete], [['collection:4', 'collection:7', 'collection:5', 'collection:2'], false, false]);
    // A repeat in a later storefront only gains its names, keeping its place and count.
    const repeated = recordItunesAnswer(first, 1, answer([collection('2', 'Five JP', 'A', 5)]), files(2), 'subset');
    assert.deepEqual([repeated.items.map(entry => [entry.key, entry.trackCount, entry.names.map(name => name.title)]), repeated.complete],
        [[['collection:2', 5, ['Five', 'Five JP']], ['collection:3', null, ['Unknown']]], true]);
    // An empty Album pairs with any collection that has tracks.
    assert.deepEqual(recordItunesAnswer(albums, 0, answer([collection('1', 'One', 'A', 1), collection('6', 'None', 'A', 0), collection('3', 'Unknown', 'A', null)]), [], 'subset')
        .items.map(entry => entry.key), ['collection:1', 'collection:3']);
    // The exact comparison is unchanged: only counts that can equal the files, in answer order, no stored count or exact-count
    // flag, and the default is exact.
    const exact = recordItunesAnswer(plain, 0, offered, files(2), 'exact');
    assert.deepEqual([exact.items.map(entry => entry.key), exact.items.some(entry => 'trackCount' in entry), 'exactComplete' in exact],
        [['collection:3', 'collection:4', 'collection:6', 'collection:7'], false, false]);
    assert.deepEqual(recordItunesAnswer(plain, 0, offered, files(2)), exact);
    // Songs are kept by a single member's duration in either mode.
    const songs = startItunesStage([recording('Synthetic Song')], 'noMatch')!;
    const heard = answer([], [song('11', '21', 'Near', 'A', { trackTimeMillis: 203_000 }), song('12', '22', 'Far', 'A', { trackTimeMillis: 203_001 })]);
    assert.deepEqual(recordItunesAnswer(songs, 0, heard, [file(200_000)], 'subset').items, recordItunesAnswer(songs, 0, heard, [file(200_000)]).items);
});

test('a review\'s stage that leaves out only collections with more tracks than members keeps its exact-count flag; an unknown or equal count, a song or an unknown member count clears it', () => {
    const albums = startItunesStage([release('Synthetic Album', { artist: 'Synthetic Artist' })], 'noMatch', 'subset')!;
    const counted = (counts: (number | null)[], from = 1) => answer(counts.map((count, index) => collection(String(from + index), `Album ${from + index}`, 'A', count)));
    // Two members, five collections of two to six tracks: the six-track one is left out, which can never have exactly two.
    const larger = recordItunesAnswer(albums, 0, counted([6, 5, 4, 3, 2]), files(2), 'subset');
    assert.deepEqual([larger.items.map(entry => entry.trackCount), larger.complete, larger.exactComplete], [[2, 3, 4, 5], false, true]);
    // Another exact count arriving later pushes out a larger one: still only larger ones left out.
    const again = recordItunesAnswer(larger, 1, counted([2], 10), files(2), 'subset');
    assert.deepEqual([again.items.map(entry => entry.trackCount), again.complete, again.exactComplete], [[2, 2, 3, 4], false, true]);
    // Five exact counts: one is left out, which could have matched exactly.
    const crowded = recordItunesAnswer(albums, 0, counted([2, 2, 2, 2, 2]), files(2), 'subset');
    assert.deepEqual([crowded.items.length, crowded.complete, crowded.exactComplete], [4, false, false]);
    // A stage read from a record without the flag starts from `complete`.
    const { exactComplete: _flag, ...unflagged } = albums;
    assert.deepEqual([recordItunesAnswer(unflagged, 0, counted([6, 5, 4, 3, 2]), files(2), 'subset').exactComplete,
        recordItunesAnswer({ ...unflagged, complete: false }, 0, counted([2]), files(2), 'subset').exactComplete], [true, false]);

    // Collection lookups skipped by the candidate bound, failed, or left by iTunes unavailable follow the same test with the member count.
    const pending = (extra: Partial<LookupItunesItem>[]) => ({ ...stageWith(extra.map((fields, index) => item(`collection:${index + 1}`, 'collection', [[`Album ${index + 1}`, 'A', 'us']],
        { bridge: 'noRelease', collection: 'pending', ...fields }))), bridge: [], finalized: true, exactComplete: true });
    const skipped = (stage: LookupItunesStage, memberCount?: number) => nextItunesCollectionAction(stage, METADATA_LOOKUP_JOB_LIMITS.candidates, false, memberCount).stage;
    const flags = (stage: LookupItunesStage) => [stage.complete, stage.exactComplete];
    assert.deepEqual(flags(skipped(pending([{ trackCount: 3 }, { trackCount: 5 }]), 2)), [false, true]);
    assert.deepEqual(flags(skipped(pending([{ trackCount: 3 }, { trackCount: 2 }]), 2)), [false, false]);
    assert.deepEqual(flags(skipped(pending([{ trackCount: 3 }, { trackCount: null }]), 2)), [false, false]);
    assert.deepEqual(flags(skipped(pending([{ trackCount: 3 }, {}]), 2)), [false, false]);
    assert.deepEqual(flags(skipped(pending([{ trackCount: 3 }]))), [false, false]);
    // A song's collection has no known count.
    const songItem = { ...stageWith([item('song:1', 'song', [['Song', 'A', 'us']], { bridge: 'noRelease', collection: 'pending' })]), bridge: [], finalized: true, exactComplete: true };
    assert.deepEqual(flags(skipped(songItem, 2)), [false, false]);
    assert.deepEqual(flags(recordItunesCollection(pending([{ trackCount: 4 }]), 'collection:1', 'failed', 2)), [false, true]);
    assert.deepEqual(flags(recordItunesCollection(pending([{ trackCount: 2 }]), 'collection:1', 'skipped', 2)), [false, false]);
    assert.deepEqual(flags(recordItunesCollection(pending([{ trackCount: 2 }]), 'collection:1', 'missing', 2)), [true, true]);
    assert.deepEqual(flags(itunesUnavailable(pending([{ trackCount: 4 }, { collection: 'fetched', trackCount: 2 }]), 2)), [false, true]);
    assert.deepEqual(flags(itunesUnavailable(pending([{ trackCount: 2 }]), 2)), [false, false]);
    // An import's stage never gains the flag.
    const { exactComplete: _absent, ...imported } = pending([{}]);
    for (const stage of [skipped(imported, 2), recordItunesCollection(imported, 'collection:1', 'failed', 2), itunesUnavailable(imported, 2)]) {
        assert.deepEqual([stage.complete, 'exactComplete' in stage], [false, false]);
    }
    // The flag and the counts are stored and read back; values of another shape are dropped.
    assert.deepEqual(storedItunesStage(JSON.parse(JSON.stringify(larger))), larger);
    const foreign = storedItunesStage({ ...larger, exactComplete: 'yes', items: larger.items.map((entry, index) => ({ ...entry, trackCount: [0, -1, '3', 2.5][index] })) })!;
    assert.deepEqual(['exactComplete' in foreign, foreign.items.map(entry => 'trackCount' in entry)], [false, [false, false, false, false]]);
});

test('a submitted Artist name is the iTunes term\'s artist, and a later release\'s Track-title search never gives an iTunes request', () => {
    const typed = (kind: 'album' | 'song') => itunesRequestsFor(planMetadataLookup({ trigger: 'submitted', fileCount: 2, submitted: { kind, text: 'Synthetic Album', artist: 'Synthetic Typed' },
        tags: { album: 'Synthetic Album', albumArtist: 'Synthetic Ensemble', title: null, artist: null } }).queries);
    for (const kind of ['album', 'song'] as const) {
        const requests = typed(kind);
        assert.deepEqual(requests.map(request => request.kind === 'itunesSearch' && [request.term, request.entity]), [['Synthetic Album Synthetic Typed', kind], ['Synthetic Album Synthetic Typed', kind]]);
        assert.equal(JSON.stringify(requests).includes('Synthetic Ensemble'), false, kind);
    }
    // A recording search a later release stores with another basis is never the iTunes text search.
    assert.deepEqual(itunesRequestsFor([{ kind: 'musicBrainzRecordingSearch', query: { recording: 'Synthetic Distinct Title' }, basis: 'trackTitle' }] as unknown[]), []);
});
